using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Xunit;
namespace MerchantOS.Admin.Tests;
public sealed class OperationalTests {
 [Fact]public async Task LivenessIsAnonymousAndDependencyIndependent(){using var app=new WebApplicationFactory<Program>();using var c=app.CreateClient(new(){BaseAddress=new("https://localhost")});Assert.Equal(System.Net.HttpStatusCode.OK,(await c.GetAsync("/health/live")).StatusCode);}
 [Fact]public void StagingCannotFallBackToEphemeralKeys(){using var app=new WebApplicationFactory<Program>().WithWebHostBuilder(b=>b.UseEnvironment("Staging"));Assert.ThrowsAny<Exception>(()=>app.CreateClient());}
 [Fact]public async Task OperationalMetricsRemainAdministratorOnly(){using var app=new WebApplicationFactory<Program>();using var c=app.CreateClient(new(){BaseAddress=new("https://localhost"),AllowAutoRedirect=false});Assert.Equal(System.Net.HttpStatusCode.Redirect,(await c.GetAsync("/ops/metrics")).StatusCode);}
 [Fact]public async Task MonitorCredentialOnlyAuthorizesSanitizedMetrics(){var file=Path.GetTempFileName();var token=Convert.ToHexString(System.Security.Cryptography.RandomNumberGenerator.GetBytes(32));await File.WriteAllTextAsync(file,token);try{using var app=new WebApplicationFactory<Program>().WithWebHostBuilder(b=>b.UseSetting("Operations:MonitorTokenFile",file));using var client=app.CreateClient(new(){BaseAddress=new("https://localhost"),AllowAutoRedirect=false});Assert.Equal(System.Net.HttpStatusCode.Unauthorized,(await client.GetAsync("/ops/monitor")).StatusCode);client.DefaultRequestHeaders.Authorization=new("Bearer",token);var response=await client.GetAsync("/ops/monitor");Assert.Equal(System.Net.HttpStatusCode.OK,response.StatusCode);var body=await response.Content.ReadAsStringAsync();Assert.Contains("requestsByStatus",body);Assert.DoesNotContain(token,body);Assert.Equal(System.Net.HttpStatusCode.Unauthorized,(await client.GetAsync("/Admin/ProductRows")).StatusCode);}finally{File.Delete(file);}}
}
